    /**
     * IC2 冷却液流体方块（NEI 显示 IC2:fluidCoolant；流体注册名 ic2coolant，GT5U 官方用法见
     * {@code GTModHandler.getIC2Coolant}）。优先按流体注册名取方块，兜底按方块注册名查找；
     * 找不到时返回 null，液体位退化为纯空气占位（不灌装）。
     */
    private static Block getCoolantBlock() {
        Fluid fluid = FluidRegistry.getFluid("ic2coolant");
        if (fluid != null) {
            Block block = fluid.getBlock();
            if (block != null) {
                return block;
            }
        }
        Block block = GameRegistry.findBlock("IC2", "blockFluidCoolant");
        if (block == null) {
            block = GameRegistry.findBlock("IC2", "fluidCoolant");
        }
        return block;
    }

