    @Override
    protected CheckRecipeResult doWirelessBusinessOnce() {
        IGregTechTileEntity base = getBaseMetaTileEntity();
        if (!mMachine || base == null || !base.isAllowedToWork()
            || !DysonMachineConfig.isInTalosOrStation(base.getWorld())) {
            return CheckRecipeResultRegistry.NO_RECIPE;
        }

        mEfficiency = 10000;
        mEfficiencyIncrease = 0;
        mMaxProgresstime = getWirelessModeProcessingTime();
        mProgresstime = 0;
        mEUt = 0;
        mOutputItems = null;
        mOutputFluids = null;

        this.lastOrundumCost = BigInteger.ZERO;
        this.lastUsedParallel = 1;

        // 奇异物质产出：按本队云与贴片数量决定，优先储存在核心中
        DysonSphereWorldData data = DysonSphereWorldData.get(base.getWorld());
        DysonTeamProgress team = data == null ? null : data.getTeam(getTeamId());
        if (team != null) {
            long gain = team.cloudCount / DysonMachineConfig.strangeMatterCloudDivisor
                + team.pasteCount / DysonMachineConfig.strangeMatterPasteDivisor;
            if (gain > 0) {
                strangeMatter += gain;
                base.markDirty();
            }
        }

        // 自动喷出：点亮“自动喷出”大节点后，产出的奇异物质每周期自动进入输出总线
        autoEjectStrangeMatter();

        return CheckRecipeResultRegistry.SUCCESSFUL;
    }

    @Override
    public void saveNBTData(NBTTagCompound aNBT) {
        aNBT.setLong("StrangeMatter", strangeMatter);
        super.saveNBTData(aNBT);
    }

    @Override
    public void loadNBTData(NBTTagCompound aNBT) {
        strangeMatter = aNBT.hasKey("StrangeMatter") ? aNBT.getLong("StrangeMatter") : 0L;
        super.loadNBTData(aNBT);
    }

    @Override
    public void onPostTick(IGregTechTileEntity aBaseMetaTileEntity, long aTick) {
        super.onPostTick(aBaseMetaTileEntity, aTick);
        if (aBaseMetaTileEntity == null || !aBaseMetaTileEntity.isServerSide()) {
            return;
        }

        // 机载全息屏同步：每 HOLO_SYNC_INTERVAL tick 重建快照，变化则推送；
        // 开机时每 HOLO_HEARTBEAT_INTERVAL tick 心跳补发（覆盖新进入射程的玩家）。
        // 放在所有早退路径之前：维度锁/完工锁/重复核心停机也会推送，保证客户端屏随之消失。
        if (aTick % HOLO_SYNC_INTERVAL == 0) {
            buildHoloSnapshot();
            if (holoDataVersion != holoSentVersion) {
                holoSentVersion = holoDataVersion;
                sendRenderDataToClient(this);
                lastHoloSendTick = aTick;
            } else if (holoMachineOn && aTick - lastHoloSendTick >= HOLO_HEARTBEAT_INTERVAL) {
                sendRenderDataToClient(this);
                lastHoloSendTick = aTick;
            }
        }

        // 队伍归属上报：离队/被踢时由系统把升级树继承到个人
        if (ownerUUID != null) {
            DysonSphereSystem.trackPlayerTeam(
                aBaseMetaTileEntity.getWorld(),
                ownerUUID,
                aBaseMetaTileEntity.getOwnerName(),
                getTeamId());
        }

        // 维度强约束：只能在塔罗斯 2 或塔罗斯-2 空间站运行，否则全部模块断开
        if (!DysonMachineConfig.isInTalosOrStation(aBaseMetaTileEntity.getWorld())) {
            disconnectAll();
            updateTeamCoreOnline(false);
            return;
        }

        // 完工锁：戴森球成型后，非胜利队伍的核心禁止开机
        DysonSphereWorldData sphereData = DysonSphereWorldData.get(aBaseMetaTileEntity.getWorld());
        if (sphereData != null && sphereData.isCompleted()
            && !(getTeamId() != null && getTeamId().equals(sphereData.getCompletedTeamId()))) {
            disableWorking();
            stopMachine(DysonModuleBase.DYSON_COMPLETED_REASON);
            disconnectAll();
            updateTeamCoreOnline(false);
            return;
        }

        // 每人一台：注册/校验唯一核心
        // 兜底：ownerUUID 未就绪（onFirstTick 时序/离线解析失败）时重新尝试
        if (ownerUUID == null) {
            this.ownerUUID = aBaseMetaTileEntity.getOwnerUuid();
        }
        UUID owner = ownerUUID;
        if (mMachine && owner != null) {
            DysonCore existing = CORE_BY_OWNER.get(owner);
            // 注册表里的旧实例可能已失效（换档/卸载残留/区块强制卸载），失效则让位
            if (existing == null
                || existing.getBaseMetaTileEntity() == null
                || existing.getBaseMetaTileEntity().isDead()) {
                CORE_BY_OWNER.put(owner, this);
                duplicateRejected = false;
            } else if (existing != this) {
                duplicateRejected = true;
                disableWorking();
                stopMachine(DUPLICATE_CORE_REASON);
                disconnectAll();
                updateTeamCoreOnline(false);
                return;
            }
        } else if (owner != null && CORE_BY_OWNER.get(owner) == this) {
            CORE_BY_OWNER.remove(owner);
            updateTeamCoreOnline(false);
        }

        // 核心算力门控：不足则全部模块断开
        boolean computeOk = false;
        if (ownerUUID != null) {
            WirelessComputeHelper.updateConsumer(this);
            computeOk = WirelessComputeHelper.isConsumerSatisfiedInGroup(this);
        }
        // 核心不在线（未成型 / 算力不足 / 被软锤停机）时全部模块断开
        // 注意：不能用 isActive()，无线模式下每轮 20 tick 之间 mMaxProgresstime 会短暂归 0，
        // 那会把模块每轮都断开重连，导致接收模块的每队唯一注册反复抖动。
        if (!mMachine || !computeOk || !aBaseMetaTileEntity.isAllowedToWork()) {
            disconnectAll();
            updateTeamCoreOnline(false);
            return;
        }
        updateTeamCoreOnline(true);

        World world = aBaseMetaTileEntity.getWorld();
        long worldTime = world.getTotalWorldTime();
        DysonSphereWorldData data = DysonSphereWorldData.get(world);
        DysonTeamProgress team = data == null ? null : data.getTeam(getTeamId());
        int paste = team == null ? 0 : team.pasteCount;
        int activeSlots = DysonMachineConfig.activeSlotsForPaste(paste);

        int connectedCount = 0;
        java.util.Iterator<DysonModuleBase<?>> it = linkedModules.iterator();
        while (it.hasNext()) {
            DysonModuleBase<?> module = it.next();
            // 清理失效引用：模块区块卸载/方块被拆后，GT 重载会新建 MTE 实例，旧实例不再有效；
            // 新实例会通过模块侧持久化的坐标在加载后自动重连，这里直接丢弃旧引用即可。
            if (module == null || module.getBaseMetaTileEntity() == null || module.getBaseMetaTileEntity().isDead()) {
                it.remove();
                continue;
            }
            // 被软锤关机的模块不允许占用连接名额；接收模块尤其不能占着“每队唯一”的名额
            if (!module.isFormed() || !module.isAllowedToWork()
                || connectedCount >= activeSlots || module.getRequiredPaste() > paste) {
                module.disconnect();
                continue;
            }
            // 接收模块每队至多 1 台：先注册成功的保持连接，后到的断开；失效后其他接收机可接管
            if (module.getModuleType() == DysonModuleBase.ModuleType.RECEIVER) {
                if (!DysonReceiverModule.tryRegisterTeamReceiver(getTeamId(), (DysonReceiverModule) module)) {
                    module.disconnect();
                    continue;
                }
            }
            // 模块自身算力
            BigInteger moduleCompute = module.getRequiredCompute();
            if (moduleCompute.signum() > 0) {
                WirelessComputeHelper.updateConsumer(module);
                if (!WirelessComputeHelper.isConsumerSatisfiedInGroup(module)) {
                    module.disconnect();
                    continue;
                }
            }
            module.connect(worldTime);
            connectedCount++;
        }
    }


    // ==================== IMTERenderer：机载全息面板 ====================

    /** 服务端：采集当前面板快照到 holo* 字段；有变化则递增版本号。 */
    private void buildHoloSnapshot() {
        IGregTechTileEntity base = getBaseMetaTileEntity();
        boolean on = base != null && mMachine && base.isAllowedToWork()
            && DysonMachineConfig.isInTalosOrStation(base.getWorld());
        DysonSphereWorldData data = base == null ? null : DysonSphereWorldData.get(base.getWorld());
        DysonTeamProgress team = data == null ? null : data.getTeam(getTeamId());
        boolean complete = data != null && data.isCompleted();
        boolean winning = complete && getTeamId() != null && getTeamId().equals(data.getCompletedTeamId());
        boolean compute = base != null && ownerUUID != null
            && WirelessComputeHelper.isConsumerSatisfiedInGroup(this);
        int linked = 0;
        for (DysonModuleBase<?> module : linkedModules) {
            if (module != null && module.isFormed() && module.isAllowedToWork()) {
                linked++;
            }
        }
        int cloud = team == null ? 0 : team.cloudCount;
        int frame = team == null ? 0 : team.frameCount;
        int paste = team == null ? 0 : team.pasteCount;
        String name = team == null ? "" : team.teamName;
        long cloudComp = getPersonalCloudComponents();
        long frameComp = getPersonalFrameComponents();
        int slots = DysonMachineConfig.activeSlotsForPaste(paste);
        // 模块列表（按链接顺序；普通断链的过滤掉 → 后续模块前移；完工锁定的保留并标记 locked）
        List<HoloModuleData> modules = new ArrayList<>();
        for (DysonModuleBase<?> module : linkedModules) {
            IGregTechTileEntity mb = module == null ? null : module.getBaseMetaTileEntity();
            if (mb == null || mb.isDead() || !module.isFormed()) {
                continue;
            }
            // 完工锁：成型后除胜利队伍接收模块外全部锁定（仍占槽位）
            boolean winnerReceiver = complete && getTeamId() != null
                && getTeamId().equals(data.getCompletedTeamId())
                && module.getModuleType() == DysonModuleBase.ModuleType.RECEIVER;
            boolean locked = complete && !winnerReceiver;
            if (!module.isAllowedToWork() && !locked) {
                continue;
            }
            HoloModuleData d = new HoloModuleData();
            d.type = module.getModuleType().ordinal();
            d.active = mb.isActive();
            d.locked = locked;
            d.dim = mb.getWorld().provider.dimensionId;
            d.x = mb.getXCoord();
            d.y = mb.getYCoord();
            d.z = mb.getZCoord();
            modules.add(d);
        }
        if (holoMachineOn != on
            || holoCloud != cloud || holoFrame != frame || holoPaste != paste
            || holoCloudComp != cloudComp || holoFrameComp != frameComp || holoStrange != strangeMatter
            || holoLinked != linked || holoSlots != slots || holoActiveSlots != slots
            || holoComputeOk != compute || holoDuplicate != duplicateRejected
            || holoComplete != complete || holoWinning != winning
            || !holoTeamName.equals(name)
            || !sameModules(holoModules, modules)) {
            holoDataVersion++;
        }
        holoMachineOn = on;
        holoTeamName = name;
        holoCloud = cloud;
        holoFrame = frame;
        holoPaste = paste;
        holoCloudComp = cloudComp;
        holoFrameComp = frameComp;
        holoStrange = strangeMatter;
        holoLinked = linked;
        holoSlots = slots;
        holoActiveSlots = slots;
        holoComputeOk = compute;
        holoDuplicate = duplicateRejected;
        holoComplete = complete;
        holoWinning = winning;
        // 面板实例列表：结构重检/换位/旋转时同步给客户端
        List<HoloPanelInstance> panels = new ArrayList<>(mHoloPanelBlocks);
        if (!samePanels(holoPanels, panels)) {
            holoPanels.clear();
            holoPanels.addAll(panels);
            holoDataVersion++;
        }
        // 模块列表：断链/新增/坐标变化时同步
        if (!sameModules(holoModules, modules)) {
            holoModules.clear();
            holoModules.addAll(modules);
            holoDataVersion++;
        }
    }

    /** 两份模块列表是否逐元素相同（用于服务端版本比对）。 */
    private static boolean sameModules(List<HoloModuleData> a, List<HoloModuleData> b) {
        if (a.size() != b.size()) {
            return false;
        }
        for (int i = 0; i < a.size(); i++) {
            HoloModuleData x = a.get(i);
            HoloModuleData y = b.get(i);
            if (x.type != y.type || x.active != y.active || x.locked != y.locked || x.dim != y.dim
                || x.x != y.x || x.y != y.y || x.z != y.z) {
                return false;
            }
        }
        return true;
    }

    /** 两份面板实例列表是否逐元素相同（用于服务端版本比对）。 */
    private static boolean samePanels(List<HoloPanelInstance> a, List<HoloPanelInstance> b) {
        if (a.size() != b.size()) {
            return false;
        }
        for (int i = 0; i < a.size(); i++) {
            if (!a.get(i).sameAs(b.get(i))) {
                return false;
            }
        }
        return true;
    }

    @Override
    public void encodeRenderData(ByteBuf buffer) {
        buffer.writeBoolean(holoMachineOn);
        // 队伍名用 DataOutput.writeUTF 兼容格式，客户端 guava ByteArrayDataInput.readUTF 读回
        try {
            ByteArrayOutputStream bos = new ByteArrayOutputStream();
            DataOutputStream dos = new DataOutputStream(bos);
            dos.writeUTF(holoTeamName == null ? "" : holoTeamName);
            dos.flush();
            buffer.writeBytes(bos.toByteArray());
        } catch (IOException ignored) {
            buffer.writeShort(0);
        }
        buffer.writeInt(holoCloud);
        buffer.writeInt(holoFrame);
        buffer.writeInt(holoPaste);
        buffer.writeLong(holoCloudComp);
        buffer.writeLong(holoFrameComp);
        buffer.writeLong(holoStrange);
        buffer.writeInt(holoLinked);
        buffer.writeInt(holoSlots);
        buffer.writeBoolean(holoComputeOk);
        buffer.writeBoolean(holoDuplicate);
        buffer.writeBoolean(holoComplete);
        buffer.writeBoolean(holoWinning);
        buffer.writeInt(holoPanels.size());
        for (HoloPanelInstance p : holoPanels) {
            buffer.writeByte(screenIdToByte(p.screenId));
            buffer.writeDouble(p.cx);
            buffer.writeDouble(p.cy);
            buffer.writeDouble(p.cz);
            buffer.writeFloat(p.rx);
            buffer.writeFloat(p.ry);
            buffer.writeFloat(p.rz);
            buffer.writeFloat(p.ux);
            buffer.writeFloat(p.uy);
            buffer.writeFloat(p.uz);
            buffer.writeFloat(p.nx);
            buffer.writeFloat(p.ny);
            buffer.writeFloat(p.nz);
        }
        // 模块列表：激活槽数 + 每台模块（类型/是否开启/维度/坐标）
        buffer.writeInt(holoActiveSlots);
        buffer.writeInt(holoModules.size());
        for (HoloModuleData d : holoModules) {
            buffer.writeInt(d.type);
            buffer.writeBoolean(d.active);
            buffer.writeBoolean(d.locked);
            buffer.writeInt(d.dim);
            buffer.writeInt(d.x);
            buffer.writeInt(d.y);
            buffer.writeInt(d.z);
        }
    }

    /** screenId 压缩为 byte（避免逐面板 UTF 序列化开销）。 */
    private static byte screenIdToByte(String id) {
        if ("dyson_modules_q".equals(id)) return 1;
        if ("dyson_modules_r".equals(id)) return 2;
        if ("dyson_modules_s".equals(id)) return 3;
        return 0;
    }

    /** byte 还原为 screenId。 */
    private static String byteToScreenId(byte b) {
        switch (b) {
            case 1:
                return "dyson_modules_q";
            case 2:
                return "dyson_modules_r";
            case 3:
                return "dyson_modules_s";
            default:
                return "";
        }
    }

    @Override
    public void decodeRenderData(ByteArrayDataInput buffer) {
        holoMachineOn = buffer.readBoolean();
        holoTeamName = buffer.readUTF();
        holoCloud = buffer.readInt();
        holoFrame = buffer.readInt();
        holoPaste = buffer.readInt();
        holoCloudComp = buffer.readLong();
        holoFrameComp = buffer.readLong();
        holoStrange = buffer.readLong();
        holoLinked = buffer.readInt();
        holoSlots = buffer.readInt();
        holoComputeOk = buffer.readBoolean();
        holoDuplicate = buffer.readBoolean();
        holoComplete = buffer.readBoolean();
        holoWinning = buffer.readBoolean();
        int panelCount = buffer.readInt();
        holoPanels.clear();
        for (int i = 0; i < panelCount; i++) {
            HoloPanelInstance p = new HoloPanelInstance();
            p.screenId = byteToScreenId(buffer.readByte());
            p.cx = buffer.readDouble();
            p.cy = buffer.readDouble();
            p.cz = buffer.readDouble();
            p.rx = buffer.readFloat();
            p.ry = buffer.readFloat();
            p.rz = buffer.readFloat();
            p.ux = buffer.readFloat();
            p.uy = buffer.readFloat();
            p.uz = buffer.readFloat();
            p.nx = buffer.readFloat();
            p.ny = buffer.readFloat();
            p.nz = buffer.readFloat();
            holoPanels.add(p);
        }
        holoActiveSlots = buffer.readInt();
        int moduleCount = buffer.readInt();
        holoModules.clear();
        for (int i = 0; i < moduleCount; i++) {
            HoloModuleData d = new HoloModuleData();
            d.type = buffer.readInt();
            d.active = buffer.readBoolean();
            d.locked = buffer.readBoolean();
            d.dim = buffer.readInt();
            d.x = buffer.readInt();
            d.y = buffer.readInt();
            d.z = buffer.readInt();
            holoModules.add(d);
        }
    }

    @Override
    @SideOnly(Side.CLIENT)
    public void renderTESR(double x, double y, double z, float timeSinceLastTick) {
        if (!holoMachineOn) {
            return;
        }
        IGregTechTileEntity base = getBaseMetaTileEntity();
        if (base == null) {
            return;
        }
        ForgeDirection facing = base.getFrontFacing();
        if (facing == null) {
            return;
        }
        // 每个面板实例各渲染一块屏：位置/朝向全部由结构检查时算好并同步（服务端），这里直接绘制。
        // 屏实例按 screenId 分派（Q/R/S 各自独立实例、独立锚点，互不串扰）。
        int bx = base.getXCoord();
        int by = base.getYCoord();
        int bz = base.getZCoord();
        for (HoloPanelInstance p : holoPanels) {
            double px = x + (p.cx - bx);
            double py = y + (p.cy - by);
            double pz = z + (p.cz - bz);
            HoloMath.Frame frame = new HoloMath.Frame();
            frame.rx = p.rx;
            frame.ry = p.ry;
            frame.rz = p.rz;
            frame.ux = p.ux;
            frame.uy = p.uy;
            frame.uz = p.uz;
            frame.nx = p.nx;
            frame.ny = p.ny;
            frame.nz = p.nz;
            HoloScreen screen = getScreenFor(p.screenId);
            HoloRender.renderScreen(screen, Minecraft.getMinecraft().fontRenderer,
                px, py, pz, frame, HoloRender.SCALE);
        }
    }

    /** 按 screenId 取/建屏实例（同类型共享实例；空 id 回退总面板）。 */
    @SideOnly(Side.CLIENT)
    private HoloScreen getScreenFor(String screenId) {
        String key = screenId == null ? "" : screenId;
        if (key.isEmpty()) {
            if (holoStatusScreen == null) {
                holoStatusScreen = new DysonStatusScreen(this);
            }
            return holoStatusScreen;
        }
        HoloScreen s = holoModuleScreens.get(key);
        if (s == null) {
            s = createPanelScreen(key);
            holoModuleScreens.put(key, s);
        }
        return s;
    }

    /** 创建模块屏（Q/R/S 三段，各显示对应槽位段）。 */
    @SideOnly(Side.CLIENT)
    private HoloScreen createPanelScreen(String key) {
        if ("dyson_modules_q".equals(key)) {
            return new DysonModuleListScreen(this, 0);
        }
        if ("dyson_modules_r".equals(key)) {
            return new DysonModuleListScreen(this, 1);
        }
        if ("dyson_modules_s".equals(key)) {
            return new DysonModuleListScreen(this, 2);
        }
        return new DysonStatusScreen(this);
    }

    @Override
    public AxisAlignedBB getRenderBoundingBox(int x, int y, int z) {
        // 包围盒 = 控制器本体 ∪ 所有面板中心，避免面板远离控制器时被视锥剔除。
        // 半径放大到 64：玩家贴近面板时相机仍在盒内，规避近距离视锥剔除导致的整面消失。
        double r = 64.0D;
        AxisAlignedBB box = AxisAlignedBB.getBoundingBox(x - r, y - r, z - r, x + 1 + r, y + 1 + r, z + 1 + r);
        for (HoloPanelInstance p : holoPanels) {
            box = box.func_111270_a(
                AxisAlignedBB.getBoundingBox(p.cx - r, p.cy - r, p.cz - r, p.cx + r, p.cy + r, p.cz + r));
        }
        return box;
    }

    @Override
    public double getMaxRenderDistanceSquared() {
        // 球体巨大，面板可能远离控制器；渲染距离与服务端数据过滤都按控制器坐标计算，
        // 必须放宽到覆盖整个球体，否则玩家靠近球面面板时因超距而既不渲染、也收不到面板数据。
        return 1.0E8D;
    }

    private void disconnectAll() {
        for (DysonModuleBase<?> module : linkedModules) {
            if (module != null) {
                module.disconnect();
            }
        }
    }

    @Override
    public void onRemoval() {
        UUID owner = ownerUUID;
        if (owner != null && CORE_BY_OWNER.get(owner) == this) {
            CORE_BY_OWNER.remove(owner);
        }
        updateTeamCoreOnline(false);
        disconnectAll();
        super.onRemoval();
    }

    @Override
    public void onUnload() {
        // 关键：区块卸载/换档时必须释放唯一核心注册，否则旧实例会残留在静态表里，
        // 导致新档/重载后的第一台核心被误判为“重复核心”而停机。
        UUID owner = ownerUUID;
        if (owner != null && CORE_BY_OWNER.get(owner) == this) {
            CORE_BY_OWNER.remove(owner);
        }
        updateTeamCoreOnline(false);
        disconnectAll();
        super.onUnload();
    }

    @Override
    public String[] getInfoData() {
        String[] origin = super.getInfoData();
        ArrayList<String> lines = new ArrayList<>(Arrays.asList(origin));

        int connectedCount = 0;
        for (DysonModuleBase<?> module : linkedModules) {
            if (module != null && module.isConnected()) {
                connectedCount++;
            }
        }

        IGregTechTileEntity base = getBaseMetaTileEntity();
        DysonSphereWorldData data = base == null ? null : DysonSphereWorldData.get(base.getWorld());
        DysonTeamProgress team = data == null ? null : data.getTeam(getTeamId());
        int paste = team == null ? 0 : team.pasteCount;

        lines.add(
            EnumChatFormatting.AQUA + Dyson_Info_ConnectedModules
                + EnumChatFormatting.GOLD
                + connectedCount
                + EnumChatFormatting.AQUA
                + " / "
                + Dyson_Info_ActiveSlots
                + EnumChatFormatting.GOLD
                + DysonMachineConfig.activeSlotsForPaste(paste));
        lines.add(
            EnumChatFormatting.AQUA + Dyson_Info_TeamPaste
                + EnumChatFormatting.GOLD
                + paste);
        lines.add(
            EnumChatFormatting.AQUA + Dyson_Info_PersonalComponents
                + EnumChatFormatting.GOLD
                + getPersonalCloudComponents()
                + EnumChatFormatting.AQUA
                + " / "
                + Dyson_Stat_Frame
                + " "
                + EnumChatFormatting.GOLD
                + getPersonalFrameComponents());
        lines.add(
            EnumChatFormatting.AQUA + Dyson_Info_StrangeMatter
                + EnumChatFormatting.GOLD
                + strangeMatter);

        if (duplicateRejected) {
            lines.add(
                EnumChatFormatting.RED + Dyson_Info_DuplicateCore);
        }

        if (base != null && base.isServerSide()) {
            // 显示用：只问本队网络供需，不要求本机已注册（停机中的重复核心也能正确显示算力状态）
            boolean computeOk = ownerUUID != null
                && WirelessComputeManager.getInstance().isNetworkSatisfiedForOwner(ownerUUID);
            lines.add(
                computeOk
                    ? EnumChatFormatting.GREEN + Dyson_Info_ComputeSatisfied
                    : EnumChatFormatting.RED + Dyson_Info_ComputeInsufficient);
        }
        return lines.toArray(new String[0]);
    }

