    @Override
    public void checkMachine(IGregTechTileEntity aBaseMetaTileEntity, ItemStack aStack,
                             List<StructureError> errors) {
        // 先清空面板收集，让本次结构检查按当前朝向重新计算（换位/旋转后不残留旧屏）
        mHoloPanelBlocks.clear();
        checkPiece(STRUCTURE_PIECE_MAIN, OffsetsX, OffsetsY, OffsetsZ, errors);
    }

    @Override
    public void construct(ItemStack stackSize, boolean hintsOnly) {
        repairMachine();
        buildPiece(STRUCTURE_PIECE_MAIN, stackSize, hintsOnly, OffsetsX, OffsetsY, OffsetsZ);
    }

    @Override
    public int survivalConstruct(ItemStack stackSize, int elementBudget, ISurvivalBuildEnvironment env) {
        if (mMachine) {
            return -1;
        }
        return survivalBuildPiece(
            STRUCTURE_PIECE_MAIN,
            stackSize,
            OffsetsX,
            OffsetsY,
            OffsetsZ,
            elementBudget,
            env,
            false,
            true);
    }

    @Override
    public IStructureDefinition<DysonCore> getStructureDefinition() {
        if (STRUCTURE_DEFINITION == null) {
            STRUCTURE_DEFINITION = StructureDefinition.<DysonCore>builder()
                .addShape(STRUCTURE_PIECE_MAIN, transpose(shapeMain))
                .addElement('A', ofBlock(ItemRegistry.bw_realglas, 0))
                .addElement('B', glowCasing(EOHBMachineBlocks.sBlockCasingsDysonFlow, 0))
                .addElement('C', ofBlock(sBlockCasings2, 6))
                .addElement('D', ofBlock(TTCasingsContainer.sBlockCasingsTT, 0))
                .addElement('E', ofBlock(TTCasingsContainer.sBlockCasingsTT, 1))
                .addElement('F', ofBlock(TTCasingsContainer.sBlockCasingsTT, 2))
                .addElement('G', ofBlock(TTCasingsContainer.sBlockCasingsTT, 3))
                .addElement('H', ofBlock(TTCasingsContainer.sBlockCasingsTT, 4))
                .addElement('I', ofBlock(sBlockFrames, 374))
                .addElement('J', buildHatchAdder(DysonCore.class)
                    .anyOf(OutputBus)
                    .casingIndex(IGTextures.CASING_INDEX_COMMAND)
                    .hint(1)
                    .buildAndChain(ofBlock(sBlockCasingsDyson, 5)))
                .addElement('K', ofBlock(sBlockCasingsDyson, 6))
                .addElement('L', ofBlock(sBlockCasingsDyson, 8))
                .addElement('M', ofBlock(sBlockCasingsDyson, 9))
                .addElement('N', liquidFillCasing(getCoolantBlock(), 0))
                .addElement('P', holoPanelCasing(
                    HoloPanelConfig.builder()
                        .forward(-0.5, -1)
                        .up(8.5)
                        .flip(true)
                        .build(),
                    sBlockCasingsDyson, 9
                    )
                )
                .addElement('Q', holoPanelCasing(
                    HoloPanelConfig.builder()
                        .screen("dyson_modules_q")
                        .left(0.5, 1)
                        .up(-5)
                        .yaw(90)
                        .build(),
                    sBlockCasingsDyson, 9
                ))
                .addElement('R', holoPanelCasing(
                    HoloPanelConfig.builder()
                        .screen("dyson_modules_r")
                        .left(-0.5, -1)
                        .up(-5)
                        .yaw(-90)
                        .build(),
                    sBlockCasingsDyson, 9
                ))
                .addElement('S', holoPanelCasing(
                    HoloPanelConfig.builder()
                        .screen("dyson_modules_s")
                        .forward(0.5, 1)
                        .up(-5)
                        .build(),
                    sBlockCasingsDyson, 9
                ))
                .build();
        }
        return STRUCTURE_DEFINITION;
    }

